const buttons=document.querySelectorAll('.menuNavBtn');const pill=document.querySelector('.pill-overlay');const sections=document.querySelectorAll('.genOplysningerContent');const intros=document.querySelectorAll('.menuIntroItem');function movePillToActive(){const activeIndex=[...buttons].findIndex(b=>b.classList.contains('active'));if(activeIndex!==-1){pill.style.left=`calc(${activeIndex * 100 / buttons.length}% + 5px)`;}}
movePillToActive();buttons.forEach((btn,index)=>{btn.addEventListener('click',()=>{buttons.forEach(b=>b.classList.remove('active'));btn.classList.add('active');pill.style.left=`calc(${index * 100 / buttons.length}% + 5px)`;sections.forEach(sec=>sec.classList.remove('activeSection'));document.getElementById(btn.dataset.target).classList.add('activeSection');intros.forEach(i=>i.classList.remove('activeIntro'));intros.forEach(i=>i.classList.remove('activeIntro'));document.getElementById(btn.dataset.intro).classList.add('activeIntro');});});